begin;
with j as (select * from jsonb_to_recordset($law7d0017$[{"code_id":"APK_RF","article_number":"30","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в порядке особого производства дела об установлении фактов, имеющих юридическое значение для возникновения, изменения и прекращения прав организаций и граждан в сфере предпринимательской и иной экономической деятельности.","article_title":"Статья 30. Компетенция арбитражных судов по делам об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3abaad70d114aae211172b4a4523756170fc36bc3714a9897f830256aa466431"},{"code_id":"APK_RF","article_number":"308.1","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные акты, указанные в части 3 настоящей статьи, могут быть пересмотрены в порядке надзора Президиумом Верховного Суда Российской Федерации по надзорным жалобам лиц, участвующих в деле, и иных лиц, указанных в статье 42 настоящего Кодекса.\n\n2. Генеральный прокурор Российской Федерации, заместители Генерального прокурора Российской Федерации вправе обратиться в Президиум Верховного Суда Российской Федерации с представлением о пересмотре определений Судебной коллегии Верховного Суда Российской Федерации, вынесенных в порядке кассационного производства по делам, указанным в части 1 статьи 52 настоящего Кодекса.\n\n3. В Президиум Верховного Суда Российской Федерации обжалуются:\n\nившие в законную силу решения и определения Судебной коллегии Верховного Суда Российской Федерации, принятые по первой инстанции, если указанные решения и определения были предметом апелляционного рассмотрения;\n\n2) определения Апелляционной коллегии Верховного Суда Российской Федерации, вынесенные по результатам рассмотрения апелляционных жалоб, представлений на решения или определения Судебной коллегии Верховного Суда Российской Федерации, принятые по первой инстанции;\n\n3) определения Судебной коллегии Верховного Суда Российской Федерации, вынесенные в порядке кассационного производства.\n\n4. Надзорные жалоба, представление на судебные акты, принятые по делам, указанным в части 3 настоящей статьи, подаются в Верховный Суд Российской Федерации в срок, не превышающий трех месяцев со дня их вступления в законную силу.\n\n5. Срок подачи надзорных жалобы, представления о пересмотре судебного акта в порядке надзора, пропущенный по причинам, не зависящим от лица, обратившегося с такими заявлением или представлением, в том числе в связи с отсутствием у него сведений об обжалуемом судебном акте, по ходатайству заинтересованного лица может быть восстановлен судьей Верховного Суда Российской Федерации при условии, что ходатайство подано не позднее чем через шесть месяцев со дня вступления в законную силу последнего оспариваемого судебного акта или, если ходатайство подано лицом, указанным в статье 42 настоящего Кодекса, со дня, когда это лицо узнало или должно было узнать о нарушении его прав или законных интересов обжалуемым судебным актом.\n\nПо результатам рассмотрения ходатайства о восстановлении пропущенного срока подачи надзорных жалобы, представления судья выносит определение об отказе в восстановлении пропущенного срока подачи надзорных жалобы, представления или о его восстановлении. (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)","article_title":"Статья 308.1. Пересмотр судебных актов в порядке надзора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58d6e9796d5823bac53f1de82acb80a82e754d7f95d59b6c847271a1f509a791"},{"code_id":"APK_RF","article_number":"308.10","version_date":"2002-07-24","article_text":"1. Председатель Верховного Суда Российской Федерации или заместитель Председателя Верховного Суда Российской Федерации по жалобе заинтересованных лиц вправе внести в Президиум Верховного Суда Российской Федерации представление о пересмотре судебных постановлений в порядке надзора в целях устранения фундаментальных нарушений норм материального права и (или) норм процессуального права, которые повлияли на законность обжалуемых судебных постановлений и лишили участников спорных материальных или процессуальных правоотношений возможности осуществления прав, гарантированных настоящим Кодексом, в том числе права на доступ к правосудию, права на справедливое судебное разбирательство на основе принципа состязательности и равноправия сторон, либо существенно ограничили эти права.\n\n2. Дело по представлению Председателя Верховного Суда Российской Федерации или заместителя Председателя Верховного Суда Российской Федерации рассматривается Президиумом Верховного Суда Российской Федерации в порядке, предусмотренном статьей 3089 настоящего Кодекса.\n\n3. Председатель Верховного Суда Российской Федерации или заместитель Председателя Верховного Суда Российской Федерации, внесшие представление, не могут участвовать в рассмотрении Президиумом Верховного Суда Российской Федерации дела, о пересмотре которого ими внесено представление.\n\n4. Жалоба, указанная в части 1 настоящей статьи, может быть подана в течение четырех месяцев со дня вступления обжалуемых судебных постановлений в законную силу.","article_title":"Статья 308.10. Пересмотр судебных постановлений в порядке надзора по представлению Председателя Верховного Суда Российской Федерации или заместителя Председателя Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04c50214e2f42b6f9d7e613e8bfb3150b1021b532c125602388aad643c396063"},{"code_id":"APK_RF","article_number":"308.11","version_date":"2002-07-24","article_text":"1. Президиум Верховного Суда Российской Федерации, рассмотрев надзорные жалобу, представление вместе с делом в порядке надзора, вправе:\n\n1) оставить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции без изменения, над\n\nзорные жалобу, представление без удовлетворения;\n\n2) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и направить дело на новое рассмотрение в соответствующий суд. При направлении дела на новое рассмотрение Президиум Верховного Суда Российской Федерации может указать на необходимость рассмотрения дела в ином составе судей;\n\n3) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и оставить заявление без рассмотрения либо прекратить производство по делу;\n\n4) оставить в силе один из принятых по делу судебных актов;\n\n5) отменить либо изменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции и принять новое судебное постановление, не передавая дело на новое рассмотрение, если допущена ошибка в применении и (или) толковании норм материального права;\n\n6) оставить надзорные жалобу, представление без рассмотрения по существу при наличии оснований, предусмотренных статьей 3083 настоящего Кодекса.\n\n2. При рассмотрении дела в порядке надзора Президиум Верховного Суда Российской Федерации проверяет правильность применения и (или) толкования норм материального права и (или) норм процессуального права судами, рассматривавшими дело, в пределах доводов, изложенных в надзорных жалобе, представлении. В интересах законности Президиум Верховного Суда Российской Федерации вправе выйти за пределы доводов, изложенных в надзорных жалобе, представлении. При этом Президиум Верховного Суда Российской Федерации не вправе проверять законность судебных актов в той части, в которой они не обжалуются, а также законность судебных актов, которые не обжалуются.\n\n3. При рассмотрении дела в порядке надзора Президиум Верховного Суда Российской Федерации не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены либо были отвергнуты судом первой или апелляционной инстанции, либо предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими и определять, какое судебное постановление должно быть принято при новом рассмотрении дела.\n\n4. Постановление Президиума Верховного Суда Российской Федерации подписывается председательствующим в заседании Президиума Верховного Суда Российской Федерации.\n\n5. Указания Президиума Верховного Суда Российской Федерации, в том числе на толкование закона, изложенные в постановлении Президиума Верховного Суда Российской Федерации, являются обязательными для суда, вновь рассматривающего дело.","article_title":"Статья 308.11. Полномочия Президиума Верховного Суда Российской Федерации при пересмотре судебных постановлений в порядке надзора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdb1e16da34854ab0c71e18206821b71335120c8adf572b11d75622dff69c720"},{"code_id":"APK_RF","article_number":"308.12","version_date":"2002-07-24","article_text":"В постановлении Президиума Верховного Суда Российской Федерации должны быть указаны:\n\n1) наименование и состав суда, принявшего постановление;\n\n2) дата и место принятия постановления;\n\n3) дело, по которому принято постановление;\n\n4) наименование лица, подавшего надзорные жалобу, представление, его процессуальное положение, место нахождения или место жительства;\n\n5) фамилия и инициалы судьи, вынесшего определение о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации;\n\n6) содержание обжалуемых судебных актов;\n\n7) выводы Президиума Верховного Суда Российской Федерации по результатам рассмотрения надзорных жалобы, представления;\n\n8) мотивы, по которым Президиум Верховного Суда Российской Федерации пришел к своим выводам, со ссылкой на законы, которыми он руководствовался при принятии постановления.","article_title":"Статья 308.12. Содержание постановления Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1b162d2a360ed115cf1f2d2137942a38070a51ad73dc1998e5f8b3e8f688d71"},{"code_id":"APK_RF","article_number":"308.13","version_date":"2002-07-24","article_text":"Постановление Президиума Верховного Суда Российской Федерации вступает в законную силу со дня его принятия и обжалованию не подлежит.\n\n(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 308.13. Вступление в законную силу постановления Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d001d61823cb4e9a077b4c3910dc4420e2b794299c5c39f12034f72b64ecca18"},{"code_id":"APK_RF","article_number":"308.2","version_date":"2002-07-24","article_text":"1. В надзорных жалобе, представлении должны быть указаны:\n\n1) наименование суда, в который они подаются;\n\n2) наименование лица, подающего надзорные жалобу, представление, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) наименования лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) наименования судов, рассматривавших дело в первой, апелляционной или кассационной инстанции, и содержание принятых ими судебных актов;\n\n5) сведения об обжалуемом судебном акте, дате его принятия и вступления в законную силу;\n\n6) предмет спора;\n\n7) основания пересмотра судебного акта в порядке надзора, предусмотренные статьей 3088 настоящего Кодекса, с приведением доводов, свидетельствующих о наличии таких оснований;\n\n8) просьба лица, подающего жалобу, представление;\n\n9) перечень документов, прилагаемых к заявлению или представлению.\n\n2. В надзорной жалобе лица, не принимавшего участия в деле, должно быть указано, какие права, свободы или законные интересы этого лица нарушены вступившим в законную силу судебным актом.\n\nДокументы, прилагаемые к надзорным жалобе, представлению, могут быть представлены в Верховный Суд Российской Федерации в электронном виде.","article_title":"Статья 308.2. Содержание надзорных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dee5618bf76f53ae2959f456ab42131f348186cd988816791ac2520009700277"},{"code_id":"APK_RF","article_number":"308.3","version_date":"2002-07-24","article_text":"1. Надзорные жалоба, представление возвращаются без рассмотрения по существу, если:\n\n1) надзорные жалоба, представление не отвечают требованиям, предусмотренным пунктами 1 - 6 и 8 части 1 и частями 3 - 5 статьи 3082 настоящего Кодекса;\n\n2) надзорные жалоба, представление поданы лицом, не имеющим права на обращение в суд надзорной инстанции, или поданы на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке надзора; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) пропущен срок обжалования судебного акта в порядке надзора, установленный частью 4 статьи 3081 настоящего Кодекса, и в надзорных жалобе, представлении не содержится ходатайство о его восстановлении или в восстановлении пропущенного срока отказано;\n\n4) поступила просьба о возвращении или об отзыве надзорных жалобы, представления;\n\n5) надзорные жалоба, представление поданы с нарушением правил подсудности, установленных частью 3 статьи 3081 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2. Надзорные жалоба, представление должны быть возвращены без рассмотрения по существу в течение десяти дней со дня их поступления в суд надзорной инстанции.","article_title":"Статья 308.3. Возвращение надзорных жалобы, представления без рассмотрения по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8bdec9a2f369352182dbb8b6e565788dffbe9b1f7fc1df7a1e3972d7ef252e0"},{"code_id":"APK_RF","article_number":"308.4","version_date":"2002-07-24","article_text":"1. Надзорные жалоба, представление, поданные в соответствии с правилами, установленными статьями 3081 и 3082 настоящего Кодекса, изучаются судьей Верховного Суда Российской Федерации.\n\n2. Судья Верховного Суда Российской Федерации изучает надзорные жалобу, представление по материалам, приложенным к ним, либо по материалам истребованного дела.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n1) об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации, если отсутствуют основания для пересмотра судебных постановлений в порядке надзора. При этом надзорные жалоба, представление, а также копии обжалуемых судебных постановлений остаются в суде надзорной инстанции;\n\n2) о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.","article_title":"Статья 308.4. Рассмотрение надзорных жалобы, представления в Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f79a76688e338d603e8e6d7881989ef8addcc1899e9378d04e4f48e537989c5"},{"code_id":"APK_RF","article_number":"308.5","version_date":"2002-07-24","article_text":"1. Надзорные жалоба, представление рассматриваются в Верховном Суде Российской Федерации в срок, не превышающий двух месяцев, если дело не было истребовано, и в срок, не превышающий трех месяцев, если дело было истребовано, не считая времени со дня истребования дела до дня его поступления в Верховный Суд Российской Федерации.\n\n2. Председатель Верховного Суда Российской Федерации, заместитель Председателя Верховного Суда Российской Федерации в случае истребования дела с учетом его сложности могут продлить срок рассмотрения надзорных жалобы, представления, но не более чем на два месяца.","article_title":"Статья 308.5. Срок рассмотрения надзорных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99ebe1882f38996eee124c7e509fc79af3ebfbb06d0c2dff88269181af3db7f7"},{"code_id":"APK_RF","article_number":"308.6","version_date":"2002-07-24","article_text":"В определении судьи Верховного Суда Российской Федерации об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего надзорные жалобу, представление, его процессуальное положение, место нахождения или место жительства;\n\n4) сведения об обжалуемом судебном акте, дата его принятия и вступления в законную силу;\n\n5) мотивы, по которым отказано в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.","article_title":"Статья 308.6. Определение об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fefe651e07d7adad03b76fd5a585e5e76ca71ed9d34a51b1ab1adf77cdf7ebc0"},{"code_id":"APK_RF","article_number":"308.7","version_date":"2002-07-24","article_text":"1. В определении судьи Верховного Суда Российской Федерации о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего надзорные жалобу, представление;\n\n4) сведения об обжалуемых судебных актах;\n\n5) содержание дела, по которому приняты обжалуемые судебные акты;\n\n6) основания передачи надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации;\n\n7) предложения судьи, вынесшего определение.\n\n2. Судья Верховного Суда Российской Федерации передает вынесенное им определение, а также надзорные жалобу, представление вместе с делом в Президиум Верховного Суда Российской Федерации.","article_title":"Статья 308.7. Определение о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10e33ad98c3bf9808404ce78172ac55c4102d9b8000743acff37e442d59023b2"},{"code_id":"APK_RF","article_number":"308.8","version_date":"2002-07-24","article_text":"Судебные постановления, указанные в части 3 статьи 3081 настоящего Кодекса, подлежат отмене или изменению, если при рассмотрении дела в порядке надзора Президиум Верховного Суда Российской Федерации установит, что соответствующее обжалуемое судебное постановление нарушает:\n\n1) права и свободы человека и гражданина, гарантированные Конституцией Российской Федерации, общепризнанными принципами и нормами международного права, международными договорами Российской Федерации;\n\n2) права и законные интересы неопределенного круга лиц или иные публичные интересы;\n\n3) единообразие в применении и (или) толковании судами норм права.","article_title":"Статья 308.8. Основания для отмены или изменения судебных постановлений в порядке надзора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b1800ef6869386870c9f2da3cbca9daf1ec913416277ba5b89b7ab7bc3cfbca6"},{"code_id":"APK_RF","article_number":"308.9","version_date":"2002-07-24","article_text":"1. Президиум Верховного Суда Российской Федерации принимает дело к рассмотрению на основании определения судьи Верховного Суда Российской Федерации о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.\n\n2. Президиум Верховного Суда Российской Федерации направляет лицам, участвующим в деле, копии определения о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации и копии надзорных жалобы, представления. Время рассмотрения надзорных жалобы, представления вместе с делом в Президиуме Верховного Суда Российской Федерации назначается с учетом того, чтобы лица, участвующие в деле, имели возможность явиться в судебное заседание.\n\n3. Лица, участвующие в деле, извещаются о времени и месте рассмотрения дела Президиумом Верховного Суда Российской Федерации. Неявка указанных лиц, надлежащим образом извещенных о времени и месте рассмотрения дела Президиумом Верховного Суда Российской Федерации, не препятствует рассмотрению дела в порядке надзора.\n\n4. Председатель Верховного Суда Российской Федерации или заместитель Председателя Верховного Суда Российской Федерации, вынесшие определение о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации, не могут участвовать в рассмотрении Президиумом Верховного Суда Российской Федерации данных надзорных жалобы, представления вместе с делом.\n\n5. Надзорные жалоба, представление вместе с делом рассматриваются Президиумом Верховного Суда Российской Федерации в судебном заседании в срок, не превышающий двух месяцев со дня вынесения судьей определения.\n\n6. В судебном заседании могут принимать участие лица, участвующие в деле, их представители, иные лица, подавшие надзорные жалобу, представление, если их права и законные интересы непосредственно затрагиваются обжалуемым судебным актом. Указанные лица могут участвовать в судебном заседании путем использования систем видеоконференц-связи в порядке, установленном статьей 1531 настоящего Кодекса.\n\n7. В случае, если прокурор является лицом, участвующим в рассмотрении дела, в судебном заседании Президиума Верховного Суда Российской Федерации принимает участие Генеральный прокурор Российской Федерации или заместитель Генерального прокурора Российской Федерации.\n\n8. Надзорные жалоба, представление вместе с делом, рассматриваемые в порядке надзора Президиумом Верховного Суда Российской Федерации, докладываются судьей Верховного Суда Российской Федерации - докладчиком по данным жалобе, представлению.\n\n9. Судья-докладчик излагает обстоятельства дела, содержание судебных постановлений, принятых по делу, доводы, содержащиеся в надзорных жалобе, представлении и послужившие основанием для передачи надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.\n\n10. Лица, указанные в части 6 настоящей статьи и явившиеся в судебное заседание, вправе дать объяснения по делу. Первым дает объяснения лицо, подавшее надзорные жалобу, представление.\n\n11. По результатам рассмотрения надзорных жалобы, представления вместе с делом Президиум Верховного Суда Российской Федерации принимает постановление.\n\n12. Вопросы, возникающие при рассмотрении надзорных жалобы, представления вместе с делом в порядке надзора, разрешаются судьями большинством голосов. При равном числе голосов, поданных за пересмотр дела и против его пересмотра, надзорные жалоба, представление считаются отклоненными.\n\n13. О принятом Президиумом Верховного Суда Российской Федерации в порядке надзора постановлении сообщается лицам, участвующим в деле.","article_title":"Статья 308.9. Порядок и срок рассмотрения надзорных жалобы, представления вместе с делом в судебном заседании Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ff75026cb8d61dc552589b9c79b1a3742d7354c11426b85b31a5afca0f5bfce"},{"code_id":"APK_RF","article_number":"309","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\nАрбитражный суд может пересмотреть принятый им и вступивший в законную силу судебный акт по новым или вновь открывшимся обстоятельствам по основаниям и в порядке, которые предусмотрены в настоящей главе. (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 309. Право арбитражного суда пересмотреть судебный акт по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"302b895adcf1697609f21bdb62924054eefc25b4d7804268de8307f4c3e09bdd"},{"code_id":"APK_RF","article_number":"31","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в соответствии с главой 30 настоящего Кодекса дела:\n\n1) об оспаривании решений третейских судов по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности;\n\n2) о выдаче исполнительных листов на принудительное исполнение решений третейских судов по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности;\n\n3) об оказании содействия третейским судам по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 31. Компетенция арбитражных судов по делам, связанным с выполнением арбитражными судами функций содействия и контроля в отношении третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1995f1b93235ad8be2cfb6d3724efe4317697228531676ba574a7827e7272433"},{"code_id":"APK_RF","article_number":"310","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 310. Арбитражные суды, пересматривающие судебные акты по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d0f26d9b6abb45c695dda3a2053fda3aafcd29f2e6544ccde517cdd3020fc91"},{"code_id":"APK_RF","article_number":"311","version_date":"2002-07-24","article_text":"1. Основаниями пересмотра судебных актов по правилам настоящей главы являются:\n\n1) вновь открывшиеся обстоятельства - указанные в части 2 настоящей статьи и существовавшие на момент принятия судебного акта обстоятельства по делу;\n\n2) новые обстоятельства - указанные в части 3 настоящей статьи, возникшие после принятия судебного акта, но имеющие существенное значение для правильного разрешения дела обстоятельства.\n\n2. Вновь открывшимися обстоятельствами являются:\n\n1) существенные для дела обстоятельства, которые не были и не могли быть известны заявителю;\n\n2) установленные вступившим в законную силу приговором суда фальсификация доказательства, заведомо ложное заключение эксперта, заведомо ложные показания свидетеля, заведомо неправильный перевод, которые повлекли за собой принятие незаконного или необоснованного судебного акта по данному делу;\n\n3) установленные вступившим в законную силу приговором суда преступные деяния лица, участвующего в деле, или его представителя либо преступные деяния судьи, совершенные при рассмотрении данного дела.\n\n21. Обстоятельства, указанные в пунктах 2 и 3 части 2 настоящей статьи, могут быть установлены помимо приговора постановлением об отказе в возбуждении уголовного дела, определением или постановлением о прекращении уголовного дела или уголовного преследования, вынесенными:\n\n1) в связи с истечением срока давности;\n\n2) в связи с устранением преступности и наказуемости деяния новым уголовным законом;\n\n3) в связи с возмещением ущерба;\n\n4) в связи с назначением меры уголовно-правового характера в виде судебного штрафа;\n\n5) в связи с применением принудительных мер воспитательного воздействия;\n\n6) в связи с применением принудительных мер медицинского характера;\n\n7) в связи со смертью обвиняемого;\n\n8) в связи с недостижением лицом возраста, с которого наступает уголовная ответственность, или отставанием несовершеннолетнего в психическом развитии, не связанном с психическим расстройством;\n\n9) в связи с деятельным раскаянием;\n\n10) в связи с примирением сторон;\n\n11) в связи с освобождением от уголовной ответственности на основании части первой статьи 781 Уголовного кодекса Российской Федерации;\n\n12) в связи с применением акта об амнистии.\n\n(Дополнение частью - Федеральный закон от 15.12.2025 № 485-ФЗ)\n\n3. Новыми обстоятельствами являются:\n\n1) отмена судебного акта арбитражного суда или суда общей юрисдикции либо постановления другого органа, послуживших основанием для принятия судебного акта по данному делу;\n\n2) признанная вступившим в законную силу судебным актом арбитражного суда или суда общей юрисдикции недействительной сделка, которая повлекла за собой принятие незаконного или необоснованного судебного акта по данному делу;\n\n3) признание постановлением Конституционного Суда Российской Федерации не соответствующим Конституции Российской Федерации или применение в истолковании, расходящемся с данным Конституционным Судом Российской Федерации в постановлении истолкованием, примененного арбитражным судом в судебном акте нормативного акта либо его отдельного положения в связи с обращением заявителя, а в случаях, предусмотренных Федеральным конституционным законом от 21 июля 1994 года № 1-ФКЗ \"О Конституционном Суде Российской Федерации\", в связи с обращением иного лица независимо от обращения заявителя в Конституционный Суд Российской Федерации; (В редакции Федерального закона от 30.12.2021 № 473-ФЗ)\n\n4) (Пункт утратил силу - Федеральный закон от 11.06.2022 № 183-ФЗ)\n\n5) определение либо изменение в постановлении Пленума Верховного Суда Российской Федерации или в постановлении Президиума Верховного Суда Российской Федерации практики применения правовой нормы, если в соответствующем акте Верховного Суда Российской Федерации содержится указание на возможность пересмотра вступивших в законную силу судебных актов в силу данного обстоятельства; (В редакции Федерального закона от 28.06.2014 № 186-ФЗ)\n\n6) установление или изменение федеральным законом оснований признания здания, сооружения или другого строения самовольной постройкой, послуживших основанием для принятия судебного акта о сносе самовольной постройки. (Дополнение пунктом - Федеральный закон от 03.08.2018 № 340-ФЗ)\n\n(Статья в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 311. Основания пересмотра судебных актов по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90e81882ec4a11848359dea85be7a9de33949a484f681d37e59bd5f9da8cd09c"}]$law7d0017$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
